    "content": "// --- MicromouseMotor.h ---
#pragma once
#include <Arduino.h>

class MicromouseMotor {
private:
    uint8_t pinIN1;
    uint8_t pinIN2;
    uint8_t ch1;   // LEDC channel for IN1
    uint8_t ch2;   // LEDC channel for IN2

    // N20 + DRV8833 + ESP32-S3 Constants
    const uint32_t PWM_FREQ = 20000; // 20 kHz (silent operation)
    const uint8_t  PWM_RES  = 10;    // 10-bit → 0–1023
    const int      MAX_PWM  = 1023;

    // MIN_POWER: minimum PWM that physically overcomes DRV8833 FET drop + motor stiction.
    // DRV8833 has ~0.6V drop per FET path. At 6V supply:
    // Effective voltage at MIN_POWER should be ~1.5V → MIN_POWER ≈ 150/1023 * 6V ≈ 0.88V
    // Start at 150, lower it if the motor stutters at very low speeds.
    const int MIN_POWER = 150;

public:
    // ch1Num / ch2Num: unique LEDC channel numbers (0–7) per motor instance.
    // Each MicromouseMotor object must use two channels that do not overlap
    // with any other peripheral using LEDC on this board.
    MicromouseMotor(uint8_t in1, uint8_t in2, uint8_t ch1Num, uint8_t ch2Num)
        : pinIN1(in1), pinIN2(in2), ch1(ch1Num), ch2(ch2Num) {}

    void begin() {
        // Arduino-ESP32 2.x LEDC API: setup channel then attach pin
        ledcSetup(ch1, PWM_FREQ, PWM_RES);
        ledcAttachPin(pinIN1, ch1);
        ledcSetup(ch2, PWM_FREQ, PWM_RES);
        ledcAttachPin(pinIN2, ch2);
        coast();
    }

    // drive(): accepts -1023 to +1023 from PID
    void drive(int speed) {
        speed = constrain(speed, -MAX_PWM, MAX_PWM);

        if (speed == 0) {
            coast();
            return;
        }

        if (speed > 0) {
            // Map PID output range into real motor-usable range [MIN_POWER, MAX_PWM]
            int pwm = map(speed, 1, MAX_PWM, MIN_POWER, MAX_PWM);
            ledcWrite(ch1, pwm);
            ledcWrite(ch2, 0);
        } else {
            int pwm = map(-speed, 1, MAX_PWM, MIN_POWER, MAX_PWM);
            ledcWrite(ch1, 0);
            ledcWrite(ch2, pwm);
        }
    }

    // brake(): active braking (slow decay — both pins HIGH)
    void brake() {
        ledcWrite(ch1, MAX_PWM);
        ledcWrite(ch2, MAX_PWM);
    }

    // coast(): free-wheel (fast decay — both pins LOW)
    void coast() {
        ledcWrite(ch1, 0);
        ledcWrite(ch2, 0);
    }
};",
